109	Expected<KernelLaunchEnvironmentTy *>
110	GenericKernelTy::getKernelLaunchEnvironment(
111	    GenericDeviceTy &GenericDevice, const KernelArgsTy &KernelArgs,
112	    const DynBlockMemConfTy &DynBlockMemConf,
113	    AsyncInfoWrapperTy &AsyncInfoWrapper, uint32_t NumBlocks0) const {
114	  // Ctor/Dtor have no arguments, replaying uses the original kernel launch
115	  // environment. Older versions of the compiler do not generate a kernel
116	  // launch environment.
117	  if ((GenericDevice.getRecordReplay() &&
118	       GenericDevice.getRecordReplay()->isReplaying()) ||
119	      KernelArgs.Version < OMP_KERNEL_ARG_MIN_VERSION_WITH_DYN_PTR)
120	    return nullptr;
121	
122	  const auto &RedCfg = KernelEnvironment.Configuration;
123	  const bool NeedsReductionBuffer = RedCfg.ReductionDataSize != 0;
124	  if (NeedsReductionBuffer && KernelArgs.Version < OMP_KERNEL_ARG_VERSION)
125	    return Plugin::error(ErrorCode::INVALID_BINARY,
126	                         "kernel was built against an older OpenMP "
127	                         "kernel-launch-environment ABI (v%u); current "
128	                         "runtime requires v%u for cross-team reductions",
129	                         KernelArgs.Version, OMP_KERNEL_ARG_VERSION);
130	  if (!NeedsReductionBuffer && !KernelArgs.DynCGroupMem)
131	    return reinterpret_cast<KernelLaunchEnvironmentTy *>(~0);
132	
133	  auto AllocOrErr = GenericDevice.dataAlloc(
134	      sizeof(KernelLaunchEnvironmentTy),
135	      /*HostPtr=*/nullptr, TargetAllocTy::TARGET_ALLOC_DEVICE, /*Alignment=*/0);
136	  if (!AllocOrErr)
137	    return AllocOrErr.takeError();
138	
139	  // Remember to free the memory later.
140	  AsyncInfoWrapper.freeAllocationAfterSynchronization(*AllocOrErr);
141	
142	  /// Use the KLE in the __tgt_async_info to ensure a stable address for the
143	  /// async data transfer.
144	  auto &LocalKLE = (*AsyncInfoWrapper).KernelLaunchEnvironment;
145	  LocalKLE = KernelLaunchEnvironment;
146	
147	  LocalKLE.DynCGroupMemSize = DynBlockMemConf.Size;
148	  LocalKLE.DynCGroupMemFbPtr = DynBlockMemConf.FallbackPtr;
149	  LocalKLE.DynCGroupMemFb = DynBlockMemConf.Fallback;
150	  LocalKLE.ReductionBuffer = nullptr;
151	
152	  if (NeedsReductionBuffer) {
153	    // Use number of teams many buffer elements.
154	    auto AllocOrErr = GenericDevice.dataAlloc(
155	        uint64_t(RedCfg.ReductionDataSize) * NumBlocks0,
156	        /*HostPtr=*/nullptr, TargetAllocTy::TARGET_ALLOC_DEVICE,
157	        /*Alignment=*/0);
158	    if (!AllocOrErr)
159	      return AllocOrErr.takeError();
160	    LocalKLE.ReductionBuffer = *AllocOrErr;
161	    // Remember to free the memory later.
162	    AsyncInfoWrapper.freeAllocationAfterSynchronization(*AllocOrErr);
163	  }
164	
165	  INFO(OMP_INFOTYPE_DATA_TRANSFER, GenericDevice.getDeviceId(),
166	       "Copying data from host to device, HstPtr=" DPxMOD ", TgtPtr=" DPxMOD
167	       ", Size=%" PRId64 ", Name=KernelLaunchEnv\n",
168	       DPxPTR(&LocalKLE), DPxPTR(*AllocOrErr),
169	       sizeof(KernelLaunchEnvironmentTy));
170	
171	  auto Err = GenericDevice.dataSubmit(*AllocOrErr, &LocalKLE,
172	                                      sizeof(KernelLaunchEnvironmentTy),
173	                                      AsyncInfoWrapper);
174	  if (Err)
175	    return Err;
176	  return static_cast<KernelLaunchEnvironmentTy *>(*AllocOrErr);
177	}
