199	Expected<DynBlockMemConfTy>
200	GenericKernelTy::prepareBlockMemory(GenericDeviceTy &GenericDevice,
201	                                    KernelArgsTy &KernelArgs,
202	                                    uint32_t NumBlocks) const {
203	  uint32_t MaxBlockMemSize = GenericDevice.getMaxBlockSharedMemSize();
204	  uint32_t DynBlockMemSize = KernelArgs.DynCGroupMem;
205	  uint32_t TotalBlockMemSize = StaticBlockMemSize + DynBlockMemSize;
206	  uint32_t DynNativeBlockMemSize = DynBlockMemSize;
207	  void *DynFallbackPtr = nullptr;
208	
209	  // No enough block memory to cover the static one. Cannot run the kernel.
210	  if (StaticBlockMemSize > MaxBlockMemSize)
211	    return Plugin::error(ErrorCode::INVALID_ARGUMENT,
212	                         "Static block memory size exceeds maximum");
213	  // No enough block memory to cover dynamic one, and the fallback is aborting.
214	  if (static_cast<DynCGroupMemFallbackType>(
215	          KernelArgs.Flags.DynCGroupMemFallback) ==
216	          DynCGroupMemFallbackType::Abort &&
217	      TotalBlockMemSize > MaxBlockMemSize)
218	    return Plugin::error(
219	        ErrorCode::INVALID_ARGUMENT,
220	        "Requested block memory size (static + dynamic) exceeds maximum");
221	
222	  DynCGroupMemFallbackType DynFallback = DynCGroupMemFallbackType::None;
223	  if (DynBlockMemSize && TotalBlockMemSize > MaxBlockMemSize) {
224	    // Launch without native dynamic block memory.
225	    DynNativeBlockMemSize = 0;
226	    DynFallback = static_cast<DynCGroupMemFallbackType>(
227	        KernelArgs.Flags.DynCGroupMemFallback);
228	    if (DynFallback != DynCGroupMemFallbackType::DefaultMem) {
229	      // Do not provide any memory as fallback.
230	      DynBlockMemSize = 0;
231	    } else {
232	      // Get global memory as fallback.
233	      auto AllocOrErr = GenericDevice.dataAlloc(
234	          NumBlocks * DynBlockMemSize,
235	          /*HostPtr=*/nullptr, TargetAllocTy::TARGET_ALLOC_DEVICE,
236	          /*Alignment=*/0);
237	      if (!AllocOrErr)
238	        return AllocOrErr.takeError();
239	      DynFallbackPtr = *AllocOrErr;
240	    }
241	  }
242	  return DynBlockMemConfTy{DynBlockMemSize, DynNativeBlockMemSize, DynFallback,
243	                           DynFallbackPtr};
244	}
245	
246	Error GenericKernelTy::launch(GenericDeviceTy &GenericDevice, void **ArgPtrs,
247	                              ptrdiff_t *ArgOffsets, KernelArgsTy &KernelArgs,
248	                              KernelExtraArgsTy *KernelExtraArgs,
249	                              AsyncInfoWrapperTy &AsyncInfoWrapper) const {
250	  llvm::SmallVector<void *, 16> Args;
251	  llvm::SmallVector<void *, 16> Ptrs;
252	
253	  uint32_t EffectiveNumThreads[3] = {KernelArgs.UserThreadLimit[0],
254	                                     KernelArgs.UserThreadLimit[1],
255	                                     KernelArgs.UserThreadLimit[2]};
256	  uint32_t EffectiveNumBlocks[3] = {KernelArgs.UserNumBlocks[0],
257	                                    KernelArgs.UserNumBlocks[1],
258	                                    KernelArgs.UserNumBlocks[2]};
259	
260	  // Multidimensional is only supported with bare mode for now.
261	  assert(isBareMode() ||
262	         EffectiveNumThreads[1] == 1 && EffectiveNumThreads[2] == 1 &&
263	             EffectiveNumBlocks[1] == 1 && EffectiveNumBlocks[2] == 1 &&
264	             "Non-bare mode should only use the first thread and block "
265	             "dimensions");
266	
267	  assert(!KernelArgs.Flags.StrictBlocksAndThreads ||
268	         EffectiveNumThreads[0] > 0 && EffectiveNumThreads[1] > 0 &&
269	             EffectiveNumThreads[2] > 0 && EffectiveNumBlocks[0] > 0 &&
270	             EffectiveNumBlocks[1] > 0 && EffectiveNumBlocks[2] > 0 &&
271	             "Strict requires number of blocks and threads greater than zero");
272	
273	  // Calculate or adjust the effective number of threads and blocks if needed.
274	  if (!KernelArgs.Flags.StrictBlocksAndThreads) {
275	    EffectiveNumThreads[0] =
276	        getEffectiveNumThreads(GenericDevice, EffectiveNumThreads[0]);
277	
278	    EffectiveNumBlocks[0] = getEffectiveNumBlocks(
279	        GenericDevice, EffectiveNumBlocks[0], KernelArgs.Tripcount,
280	        EffectiveNumThreads[0], KernelArgs.UserThreadLimit[0] > 0);
281	  }
282	
283	  auto DynBlockMemConfOrErr = prepareBlockMemory(
284	      GenericDevice, KernelArgs,
285	      EffectiveNumBlocks[0] * EffectiveNumBlocks[1] * EffectiveNumBlocks[2]);
286	  if (!DynBlockMemConfOrErr)
287	    return DynBlockMemConfOrErr.takeError();
288	
289	  DynBlockMemConfTy &DynBlockMemConf = *DynBlockMemConfOrErr;
290	  if (DynBlockMemConf.FallbackPtr)
291	    AsyncInfoWrapper.freeAllocationAfterSynchronization(
292	        DynBlockMemConf.FallbackPtr);
293	
294	  auto KernelLaunchEnvOrErr =
295	      getKernelLaunchEnvironment(GenericDevice, KernelArgs, DynBlockMemConf,
296	                                 AsyncInfoWrapper, EffectiveNumBlocks[0]);
297	  if (!KernelLaunchEnvOrErr)
298	    return KernelLaunchEnvOrErr.takeError();
299	
300	  KernelLaunchParamsTy LaunchParams;
301	
302	  // Kernel languages do not use the OpenMP indirection and argument parsing.
303	  if (KernelArgs.Flags.IsCUDA) {
304	    LaunchParams =
305	        *reinterpret_cast<KernelLaunchParamsTy *>(KernelArgs.ArgPtrs);
306	  } else if (KernelArgs.Flags.IsPtrArgs) {
307	    LaunchParams = KernelLaunchParamsTy{KernelArgs.NumArgs, KernelArgs.ArgPtrs};
308	  } else {
309	    LaunchParams =
310	        prepareArgs(GenericDevice, ArgPtrs, ArgOffsets, KernelArgs.NumArgs,
311	                    Args, Ptrs, *KernelLaunchEnvOrErr, KernelArgs.Version);
312	  }
313	
314	  if (auto Err = printLaunchInfo(GenericDevice, KernelArgs, EffectiveNumThreads,
315	                                 EffectiveNumBlocks))
316	    return Err;
317	
318	  RecordReplayTy::HandleTy RRHandle;
319	  RecordReplayTy *RecordReplay = GenericDevice.getRecordReplay();
320	  if (RecordReplay) {
321	    // Record replay requires synchronization of any previous operation.
322	    if (auto Err = AsyncInfoWrapper.synchronize())
323	      return Err;
324	
325	    // Record the kernel prologue data before kernel launch.
326	    auto RRHandleOrErr = RecordReplay->recordPrologue(
327	        *this, KernelArgs, KernelExtraArgs, LaunchParams, EffectiveNumBlocks,
328	        EffectiveNumThreads, DynBlockMemConf.NativeSize);
329	    if (!RRHandleOrErr)
330	      return RRHandleOrErr.takeError();
331	    RRHandle = *RRHandleOrErr;
332	  }
333	
334	  if (auto Err = launchImpl(GenericDevice, EffectiveNumThreads,
335	                            EffectiveNumBlocks, DynBlockMemConf.NativeSize,
336	                            KernelArgs, LaunchParams, AsyncInfoWrapper))
337	    return Err;
338	
339	  if (RecordReplay) {
340	    // Record replay requires synchronization.
341	    if (auto Err = AsyncInfoWrapper.synchronize())
342	      return Err;
343	
344	    // Record the epilogue data after kernel synchronization.
345	    return RecordReplay->recordEpilogue(*this, RRHandle);
346	  }
347	  return Plugin::success();
348	}
349	
350	KernelLaunchParamsTy
351	GenericKernelTy::prepareArgs(GenericDeviceTy &GenericDevice, void **ArgPtrs,
352	                             ptrdiff_t *ArgOffsets, uint32_t &NumArgs,
353	                             llvm::SmallVectorImpl<void *> &Args,
354	                             llvm::SmallVectorImpl<void *> &Ptrs,
355	                             KernelLaunchEnvironmentTy *KernelLaunchEnvironment,
356	                             uint32_t Version) const {
357	  if (NumArgs == 0)
358	    return KernelLaunchParamsTy{};
359	
360	  // The argument arrays already include the dyn_ptr slot at the end (appended
361	  // by the host for version >= 4, or by upgradeKernelArgs for version 3).
362	  Args.resize(NumArgs);
363	  Ptrs.resize(NumArgs);
364	
365	  for (uint32_t I = 0; I < NumArgs; ++I)
366	    Args[I] = reinterpret_cast<void *>(reinterpret_cast<intptr_t>(ArgPtrs[I]) +
367	                                       ArgOffsets[I]);
368	
369	  // Optionally assign the KernelLaunchEnvironment to the last slot (dyn_ptr).
370	  if (KernelLaunchEnvironment)
371	    Args[NumArgs - 1] = KernelLaunchEnvironment;
372	
373	  // Version 3 device kernels have dyn_ptr baked in at position 0. Rotate the
374	  // last element to the front to match the device ABI.
375	  if (Version <= OMP_KERNEL_ARG_MIN_VERSION_WITH_DYN_PTR &&
376	      KernelLaunchEnvironment)
377	    std::rotate(Args.begin(), Args.end() - 1, Args.end());
378	
379	  for (uint32_t I = 0; I < NumArgs; ++I)
380	    Ptrs[I] = &Args[I];
381	
382	  return KernelLaunchParamsTy{NumArgs, &Ptrs[0]};
383	}
384	
385	uint32_t
386	GenericKernelTy::getEffectiveNumThreads(GenericDeviceTy &GenericDevice,
387	                                        uint32_t UserThreadLimit) const {
388	  assert(!isBareMode() && "bare kernel should not call this function");
389	
390	  if (UserThreadLimit > 0 && isGenericMode())
391	    UserThreadLimit += GenericDevice.getWarpSize();
392	
393	  return std::min(MaxNumThreads, (UserThreadLimit > 0) ? UserThreadLimit
394	                                                       : PreferredNumThreads);
395	}
396	
397	uint32_t GenericKernelTy::getEffectiveNumBlocks(
398	    GenericDeviceTy &GenericDevice, uint32_t UserNumBlocks,
399	    uint64_t LoopTripCount, uint32_t &EffectiveNumThreads,
400	    bool IsNumThreadsFromUser) const {
401	  assert(!isBareMode() && "bare kernel should not call this function");
